      { sku: 'TALK', qty: 1 },
    ],
  });
  const totals = invoiceTotals(invoice.value);
  const workshopTotal = 2 * 60000;
  const workshopDiscount = workshopTotal * 10 / 100;
  const talkTotal = 1 * 35000;
  assert.equal(totals.subtotal, workshopTotal + talkTotal);
  assert.equal(totals.discount, workshopDiscount);
