});

test('invoiceTotals includes voucher in return value', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const totals = invoiceTotals(invoice);
  assert.ok(totals.voucher !== undefined);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals calculates total with voucher', () => {
  let invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const voucherResult = applyVoucher(invoice, { code: 'WELCOME10', amount: 10000 });
  const totals = invoiceTotals(voucherResult.value);
  assert.equal(totals.voucher, 10000);
  assert.equal(totals.total, 60000 - 10000);
});

test('applyVoucher adds voucher to draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
