    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  invoice = issueInvoice(invoice, []).value;
  const result = applyVoucher(invoice, { code: 'WELCOME10', amount: 10000 });
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher reports VOUCHER_EXISTS if one already applied', () => {
