test('invoiceTotals calculates total including discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 2, discountPercent: 10 },
      { sku: 'TALK', qty: 1 },
    ],
  });
  const totals = invoiceTotals(invoice.value);
  const workshopTotal = 2 * 60000;
  const workshopDiscount = workshopTotal * 10 / 100;
  const talkTotal = 1 * 35000;
  assert.equal(totals.subtotal, workshopTotal + talkTotal);
  assert.equal(totals.discount, workshopDiscount);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, workshopTotal - workshopDiscount + talkTotal);
});

